   224  static int
   225  secondline_is_bases(const unsigned char *u, const unsigned char *ulim)
   226  {
   227      // Skip to second line, returning false if there isn't one
   228      u = memchr(u, '\n', ulim - u);
   229      if (u == NULL || ++u == ulim) return 0;
   230
   231      // Scan over all base-encoding letters (including 'N' but not SEQ's '=')
   232      while (u < ulim && (seq_nt16_table[*u] != 15 || toupper(*u) == 'N')) {
   233          if (*u == '=') return 0;
   234          u++;
   235      }
   236
   237      return (u == ulim || *u == '\r' || *u == '\n')? 1 : 0;
   238  }
