   299  // Match COLUMNS as a prefix against PATTERN (so COLUMNS may run out first).
   300  // Returns len(COLUMNS) (modulo '+'), or 0 if there is a mismatched entry.
   301  static int colmatch(const char *columns, const char *pattern)
   302  {
   303      int i;
   304      for (i = 0; columns[i] != '\0'; i++) {
   305          if (pattern[i] == '+') return i;
   306          if (! (columns[i] == pattern[i] || pattern[i] == 'Z')) return 0;
   307      }
   308
   309      return i;
   310  }
